import dagger.hilt.android.testing.HiltTestApplication

class HiltTestRunner : AndroidJUnitRunner() {
    override fun newApplication(
        cl: ClassLoader?,
        className: String?,
        context: Context?
    ): Application {
        return super.newApplication(cl, HiltTestApplication::class.java.name, context)
    }
}

package com.example.hannibalsguide

import androidx.compose.ui.test.junit4.createAndroidComposeRule
import androidx.compose.ui.test.onAllNodesWithText
import org.junit.Rule
import org.junit.Test
import org.junit.Assert.assertTrue
import org.junit.Assume

class HomeScreenUiTest {
    @get:Rule
    val composeRule = createAndroidComposeRule<MainActivity>()

    @Test
    fun homeScreenShowsTitleAndSearch() {
        assumeComposeHierarchyReady()
        val titles = listOf("Discover Tunisia", "Decouvrir la Tunisie", "اكتشف تونس")
        val placeholders = listOf(
            "Search by name, city, or heritage",
            "Rechercher par nom, ville ou patrimoine",
            "ابحث بالاسم او المدينة او التراث"
        )

        composeRule.waitUntil(timeoutMillis = 15_000) {
            titles.any { title ->
                composeRule.onAllNodesWithText(title).fetchSemanticsNodes().isNotEmpty()
            }
        }

        val titleFound = titles.any { title ->
            composeRule.onAllNodesWithText(title).fetchSemanticsNodes().isNotEmpty()
        }
        val placeholderFound = placeholders.any { text ->
            composeRule.onAllNodesWithText(text).fetchSemanticsNodes().isNotEmpty()
        }

        assertTrue("Expected a localized app title to be visible.", titleFound)
        assertTrue("Expected a localized search placeholder to be visible.", placeholderFound)
    }

    private fun assumeComposeHierarchyReady() {
        try {
            composeRule.onAllNodesWithText(" ").fetchSemanticsNodes()
        } catch (e: IllegalStateException) {
            Assume.assumeTrue("Compose hierarchy not available on this device.", false)
        }
    }
}

package com.example.hannibalsguide

import androidx.compose.ui.test.assertCountEquals
import androidx.compose.ui.test.assertIsDisplayed
import androidx.compose.ui.test.junit4.createAndroidComposeRule
import androidx.compose.ui.test.onAllNodesWithText
import androidx.compose.ui.test.onAllNodesWithContentDescription
import androidx.compose.ui.test.onNodeWithContentDescription
import androidx.compose.ui.test.onNodeWithText
import androidx.compose.ui.test.performClick
import org.junit.Assert.assertTrue
import org.junit.Assume
import org.junit.Rule
import org.junit.Test

class NavigationUiTest {
    @get:Rule
    val composeRule = createAndroidComposeRule<MainActivity>()

    @Test
    fun settingsNavigationAndLanguageSwitchUpdatesUi() {
        assumeComposeHierarchyReady()
        waitForAnyContentDescription(listOf("Settings", "Parametres", "الاعدادات"))

        clickFirstByContentDescription(listOf("Settings", "Parametres", "الاعدادات"))
        assertAnyTextVisible(listOf("Settings", "Parametres", "الاعدادات"))
        assertAnyTextVisible(listOf("Language", "Langue", "اللغة"))

        clickFirstByText(listOf("Francais", "French", "الفرنسية"))
        waitForAnyText(listOf("Parametres", "الاعدادات"))
        assertAnyTextVisible(listOf("Parametres", "الاعدادات"))

        clickFirstByText(listOf("English", "Anglais", "الانجليزية"))
        waitForAnyText(listOf("Discover Tunisia", "Decouvrir la Tunisie", "اكتشف تونس"))
    }

    @Test
    fun detailAndChatNavigationShowsExpectedScreens() {
        assumeComposeHierarchyReady()
        val landmarkName = waitForAnyText(
            listOf("El Jem Amphitheatre", "Amphitheatre d'El Jem", "مدرج الجم")
        )

        composeRule.onNodeWithText(landmarkName).performClick()

        val askTarekLabel = waitForAnyText(listOf("Ask Tarek", "Demander a Tarek", "اسال طارق"))
        val chatTitleLabel = listOf("Chat with Tarek", "Discussion avec Tarek", "دردشة مع طارق")
        val chatPlaceholder = listOf(
            "Ask about this place...",
            "Demandez a propos de ce lieu...",
            "اسال عن هذا المكان..."
        )

        composeRule.onNodeWithText(askTarekLabel).assertIsDisplayed()
        composeRule.onNodeWithText(askTarekLabel).performClick()

        assertAnyTextVisible(chatTitleLabel)
        assertAnyTextVisible(chatPlaceholder)
    }

    @Test
    fun mapNavigationHidesDetailActions() {
        assumeComposeHierarchyReady()
        val landmarkName = waitForAnyText(
            listOf("El Jem Amphitheatre", "Amphitheatre d'El Jem", "مدرج الجم")
        )

        composeRule.onNodeWithText(landmarkName).performClick()
        val viewOnMapLabel = waitForAnyText(listOf("View on Map", "Voir sur la carte", "عرض على الخريطة"))
        composeRule.onNodeWithText(viewOnMapLabel).performClick()

        assertAnyContentDescriptionVisible(listOf("Back", "Retour", "رجوع"))
        composeRule.onAllNodesWithText(viewOnMapLabel).assertCountEquals(0)
    }

    private fun waitForAnyText(candidates: List<String>): String {
        composeRule.waitUntil(timeoutMillis = 15_000) {
            candidates.any { text ->
                composeRule.onAllNodesWithText(text).fetchSemanticsNodes().isNotEmpty()
            }
        }
        return candidates.first { text ->
            composeRule.onAllNodesWithText(text).fetchSemanticsNodes().isNotEmpty()
        }
    }

    private fun clickFirstByText(candidates: List<String>) {
        val text = candidates.firstOrNull { candidate ->
            composeRule.onAllNodesWithText(candidate).fetchSemanticsNodes().isNotEmpty()
        }
        requireNotNull(text) { "None of the expected texts were found: $candidates" }
        composeRule.onNodeWithText(text).performClick()
    }

    private fun clickFirstByContentDescription(candidates: List<String>) {
        val description = candidates.firstOrNull { candidate ->
            composeRule.onAllNodesWithContentDescription(candidate, useUnmergedTree = true)
                .fetchSemanticsNodes().isNotEmpty()
        }
        requireNotNull(description) { "None of the expected descriptions were found: $candidates" }
        composeRule.onNodeWithContentDescription(description, useUnmergedTree = true).performClick()
    }

    private fun assertAnyTextVisible(candidates: List<String>) {
        val found = candidates.any { text ->
            composeRule.onAllNodesWithText(text).fetchSemanticsNodes().isNotEmpty()
        }
        assertTrue("Expected one of the texts to be visible: $candidates", found)
    }

    private fun assertAnyContentDescriptionVisible(candidates: List<String>) {
        val found = candidates.any { description ->
            composeRule.onAllNodesWithContentDescription(description, useUnmergedTree = true)
                .fetchSemanticsNodes().isNotEmpty()
        }
        assertTrue("Expected one of the content descriptions to be visible: $candidates", found)
    }

    private fun waitForAnyContentDescription(candidates: List<String>): String {
        composeRule.waitUntil(timeoutMillis = 15_000) {
            candidates.any { description ->
                composeRule.onAllNodesWithContentDescription(description, useUnmergedTree = true)
                    .fetchSemanticsNodes().isNotEmpty()
            }
        }
        return candidates.first { description ->
            composeRule.onAllNodesWithContentDescription(description, useUnmergedTree = true)
                .fetchSemanticsNodes().isNotEmpty()
        }
    }

    private fun assumeComposeHierarchyReady() {
        try {
            composeRule.onAllNodesWithText(" ").fetchSemanticsNodes()
        } catch (e: IllegalStateException) {
            Assume.assumeTrue("Compose hierarchy not available on this device.", false)
        }
    }
}

package com.example.hannibalsguide

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.hilt.navigation.compose.hiltViewModel
import androidx.navigation.NavType
import androidx.navigation.compose.*
import androidx.navigation.navArgument
import com.example.hannibalsguide.presentation.chat.ChatScreen
import com.example.hannibalsguide.presentation.chat.ChatViewModel
import com.example.hannibalsguide.presentation.home.HomeScreen
import com.example.hannibalsguide.presentation.home.HomeViewModel
import com.example.hannibalsguide.presentation.landmarkdetail.DetailScreen
import com.example.hannibalsguide.presentation.landmarkdetail.DetailViewModel
import com.example.hannibalsguide.presentation.map.MapScreen
import com.example.hannibalsguide.presentation.map.MapViewModel
import com.example.hannibalsguide.ui.theme.HannibalsGuideTheme
import dagger.hilt.android.AndroidEntryPoint

@AndroidEntryPoint
class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent {
            HannibalsGuideTheme {
                val navController = rememberNavController()

                NavHost(navController = navController, startDestination = "home") {
                    composable("home") {
                        val vm: HomeViewModel = hiltViewModel()
                        HomeScreen(
                            viewModel = vm,
                            onLandmarkClick = { id -> navController.navigate("detail/$id") }
                        )
                    }

                    composable(
                        "detail/{id}",
                        arguments = listOf(navArgument("id") { type = NavType.StringType })
                    ) { backStackEntry ->
                        val id = backStackEntry.arguments?.getString("id").orEmpty()
                        val vm: DetailViewModel = hiltViewModel()
                        DetailScreen(
                            viewModel = vm,
                            landmarkId = id,
                            onBack = { navController.popBackStack() },
                            onAskTarek = { lmId -> navController.navigate("chat/$lmId") },
                            onOpenMap = { lmId -> navController.navigate("map/$lmId") }
                        )
                    }

                    composable("chat/{id}") { backStackEntry ->
                        val id = backStackEntry.arguments?.getString("id").orEmpty()
                        val vm: ChatViewModel = hiltViewModel()
                        ChatScreen(
                            viewModel = vm,
                            landmarkId = id,
                            onBack = { navController.popBackStack() }
                        )
                    }

                    composable("map/{id}") { backStackEntry ->
                        val id = backStackEntry.arguments?.getString("id").orEmpty()
                        val vm: MapViewModel = hiltViewModel()
                        MapScreen(
                            viewModel = vm,
                            landmarkId = id,
                            onBack = { navController.popBackStack() }
                        )
                    }
                }
            }
        }
    }
}

package com.example.hannibalsguide

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.hilt.navigation.compose.hiltViewModel
import androidx.navigation.NavType
import androidx.navigation.compose.*
import androidx.navigation.navArgument
import com.example.hannibalsguide.presentation.chat.ChatScreen
import com.example.hannibalsguide.presentation.chat.ChatViewModel
import com.example.hannibalsguide.presentation.home.HomeScreen
import com.example.hannibalsguide.presentation.home.HomeViewModel
import com.example.hannibalsguide.presentation.landmarkdetail.DetailScreen
import com.example.hannibalsguide.presentation.landmarkdetail.DetailViewModel
import com.example.hannibalsguide.presentation.map.MapScreen
import com.example.hannibalsguide.presentation.map.MapViewModel
import com.example.hannibalsguide.presentation.settings.LanguageViewModel
import com.example.hannibalsguide.presentation.settings.SettingsScreen
import com.example.hannibalsguide.ui.theme.HannibalsGuideTheme
import dagger.hilt.android.AndroidEntryPoint
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.ui.platform.LocalLayoutDirection
import androidx.compose.ui.unit.LayoutDirection

@AndroidEntryPoint
class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent {
            val languageViewModel: LanguageViewModel = hiltViewModel()
            val language by languageViewModel.language.collectAsState()
            androidx.compose.runtime.CompositionLocalProvider(
                LocalLayoutDirection provides if (language.isRtl) LayoutDirection.Rtl else LayoutDirection.Ltr
            ) {
                HannibalsGuideTheme {
                    val navController = rememberNavController()

                    NavHost(navController = navController, startDestination = "home") {
                        composable("home") {
                            val vm: HomeViewModel = hiltViewModel()
                            HomeScreen(
                                viewModel = vm,
                                onLandmarkClick = { id -> navController.navigate("detail/$id") },
                                onSettingsClick = { navController.navigate("settings") }
                            )
                        }

                        composable(
                            "detail/{id}",
                            arguments = listOf(navArgument("id") { type = NavType.StringType })
                        ) { backStackEntry ->
                            val id = backStackEntry.arguments?.getString("id").orEmpty()
                            val vm: DetailViewModel = hiltViewModel()
                            DetailScreen(
                                viewModel = vm,
                                landmarkId = id,
                                onBack = { navController.popBackStack() },
                                onAskTarek = { lmId -> navController.navigate("chat/$lmId") },
                                onOpenMap = { lmId -> navController.navigate("map/$lmId") }
                            )
                        }

                        composable("chat/{id}") { backStackEntry ->
                            val id = backStackEntry.arguments?.getString("id").orEmpty()
                            val vm: ChatViewModel = hiltViewModel()
                            ChatScreen(
                                viewModel = vm,
                                landmarkId = id,
                                onBack = { navController.popBackStack() }
                            )
                        }

                        composable("map/{id}") { backStackEntry ->
                            val id = backStackEntry.arguments?.getString("id").orEmpty()
                            val vm: MapViewModel = hiltViewModel()
                            MapScreen(
                                viewModel = vm,
                                landmarkId = id,
                                onBack = { navController.popBackStack() }
                            )
                        }

                        composable("settings") {
                            val vm: LanguageViewModel = hiltViewModel()
                            SettingsScreen(
                                viewModel = vm,
                                onBack = { navController.popBackStack() }
                            )
                        }
                    }
                }
            }
        }
    }
}

package com.example.hannibalsguide.data.local

import android.content.Context
import com.example.hannibalsguide.data.local.dto.LandmarkDto
import com.example.hannibalsguide.domain.model.Landmark
import com.google.gson.Gson
import com.google.gson.reflect.TypeToken
import dagger.hilt.android.qualifiers.ApplicationContext
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class LandmarkLocalDataSource @Inject constructor(
    @ApplicationContext private val context: Context
) {
    fun loadLandmarks(): List<Landmark> {
        return try {
            val json = context.assets.open("landmarks_tn.json")
                .bufferedReader()
                .use { it.readText() }

            val type = object : TypeToken<List<LandmarkDto>>() {}.type
            val dtos: List<LandmarkDto> = Gson().fromJson(json, type)
            dtos.map { it.toDomain() }
        } catch (e: Exception) {
            emptyList()
        }
    }
}

package com.example.hannibalsguide.data.local

import android.content.Context
import com.example.hannibalsguide.data.local.dto.LandmarkDto
import com.example.hannibalsguide.domain.model.AppLanguage
import com.example.hannibalsguide.domain.model.Landmark
import com.google.gson.Gson
import com.google.gson.reflect.TypeToken
import dagger.hilt.android.qualifiers.ApplicationContext
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class LandmarkLocalDataSource @Inject constructor(
    @ApplicationContext private val context: Context
) {
    fun loadLandmarks(language: AppLanguage): List<Landmark> {
        return try {
            val fileName = when (language) {
                AppLanguage.ENGLISH -> "landmarks_tn.json"
                AppLanguage.FRENCH -> "landmarks_tn_fr.json"
                AppLanguage.ARABIC -> "landmarks_tn_ar.json"
            }
            val json = context.assets.open(fileName)
                .bufferedReader()
                .use { it.readText() }

            val type = object : TypeToken<List<LandmarkDto>>() {}.type
            val dtos: List<LandmarkDto> = Gson().fromJson(json, type)
            dtos.map { it.toDomain() }
        } catch (e: Exception) {
            emptyList()
        }
    }
}

package com.example.hannibalsguide.data.preferences

import android.content.Context
import androidx.datastore.preferences.core.Preferences
import androidx.datastore.preferences.core.edit
import androidx.datastore.preferences.core.stringPreferencesKey
import androidx.datastore.preferences.preferencesDataStore
import com.example.hannibalsguide.domain.model.AppLanguage
import com.example.hannibalsguide.domain.repository.LanguageRepository
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.map
import javax.inject.Inject
import javax.inject.Singleton

private val Context.dataStore by preferencesDataStore(name = "app_settings")

@Singleton
class LanguageRepositoryImpl @Inject constructor(
    @ApplicationContext private val context: Context
) : LanguageRepository {

    private val languageKey = stringPreferencesKey("app_language")

    override val languageFlow: Flow<AppLanguage> = context.dataStore.data.map { prefs: Preferences ->
        AppLanguage.fromCode(prefs[languageKey])
    }

    override suspend fun setLanguage(language: AppLanguage) {
        context.dataStore.edit { prefs ->
            prefs[languageKey] = language.code
        }
    }

    override suspend fun getLanguage(): AppLanguage {
        return AppLanguage.fromCode(context.dataStore.data.first()[languageKey])
    }
}

package com.example.hannibalsguide.data.repository

import com.example.hannibalsguide.data.local.LandmarkLocalDataSource
import com.example.hannibalsguide.domain.model.Landmark
import com.example.hannibalsguide.domain.repository.LandmarkRepository
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class LandmarkRepositoryImpl @Inject constructor(
    private val localDataSource: LandmarkLocalDataSource
) : LandmarkRepository {

    private val cached: List<Landmark> by lazy { localDataSource.loadLandmarks() }

    override suspend fun getLandmarks(): List<Landmark> = cached

    override suspend fun searchLandmarks(query: String): List<Landmark> {
        val q = query.trim().lowercase()
        if (q.isBlank()) return cached

        return cached.filter {
            it.name.lowercase().contains(q) ||
                    it.city.lowercase().contains(q) ||
                    it.category.lowercase().contains(q)
        }
    }

    override suspend fun getLandmarkById(id: String): Landmark? {
        return cached.firstOrNull { it.id == id }
    }
}

package com.example.hannibalsguide.data.repository

import com.example.hannibalsguide.data.local.LandmarkLocalDataSource
import com.example.hannibalsguide.domain.model.AppLanguage
import com.example.hannibalsguide.domain.model.Landmark
import com.example.hannibalsguide.domain.repository.LandmarkRepository
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class LandmarkRepositoryImpl @Inject constructor(
    private val localDataSource: LandmarkLocalDataSource
) : LandmarkRepository {

    private val cachedByLanguage = mutableMapOf<AppLanguage, List<Landmark>>()

    override suspend fun getLandmarks(language: AppLanguage): List<Landmark> {
        return cachedByLanguage.getOrPut(language) { localDataSource.loadLandmarks(language) }
    }

    override suspend fun searchLandmarks(query: String, language: AppLanguage): List<Landmark> {
        val q = query.trim().lowercase()
        if (q.isBlank()) return getLandmarks(language)

        return getLandmarks(language).filter {
            it.name.lowercase().contains(q) ||
                    it.city.lowercase().contains(q) ||
                    it.category.lowercase().contains(q)
        }
    }

    override suspend fun getLandmarkById(id: String, language: AppLanguage): Landmark? {
        return getLandmarks(language).firstOrNull { it.id == id }
    }
}

