@Composable
fun HomeScreen(
    viewModel: HomeViewModel,
    onLandmarkClick: (String) -> Unit,
    onSettingsClick: () -> Unit
) {
    val landmarks by viewModel.landmarks.collectAsState()
    var query by remember { mutableStateOf("") }
    val languageViewModel: LanguageViewModel = hiltViewModel()
    val language by languageViewModel.language.collectAsState()
    val strings = UiStrings(language)

    LaunchedEffect(Unit) { viewModel.loadLandmarks() }

    HomeScreenContent(
        landmarks = landmarks,
        query = query,
        strings = strings,
        onQueryChange = {
            query = it
            viewModel.search(it)
        },
        onLandmarkClick = onLandmarkClick,
        onSettingsClick = onSettingsClick
    )
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun HomeScreenContent(
    landmarks: List<Landmark>,
    query: String,
    strings: UiStrings,
    onQueryChange: (String) -> Unit,
    onLandmarkClick: (String) -> Unit,
    onSettingsClick: () -> Unit
) {
    Scaffold(
        containerColor = MaterialTheme.colorScheme.background,
        topBar = {
            CenterAlignedTopAppBar(
                title = { Text(strings.appTitle) },
                actions = {
                    IconButton(onClick = onSettingsClick) {
                        Icon(
                            imageVector = Icons.Rounded.Settings,
                            contentDescription = strings.settingsContentDescription
                        )
                    }
                },
                colors = TopAppBarDefaults.centerAlignedTopAppBarColors(
                    containerColor = MaterialTheme.colorScheme.background
                )
            )
        }
    ) { padding ->
        TunisianPatternBackground(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
        ) {
            Column(modifier = Modifier.fillMaxSize()) {
                OutlinedTextField(
                    value = query,
                    onValueChange = onQueryChange,
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp, vertical = 10.dp),
                    placeholder = { Text(strings.searchPlaceholder) },
                    singleLine = true,
                    leadingIcon = { Icon(Icons.Rounded.Search, contentDescription = strings.searchPlaceholder) },
                    shape = androidx.compose.foundation.shape.RoundedCornerShape(14.dp)
                )

                LazyColumn(
                    modifier = Modifier.fillMaxSize(),
                    contentPadding = PaddingValues(horizontal = 16.dp, vertical = 8.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    items(landmarks) { landmark ->
                        LandmarkItem(
                            landmark = landmark,
                            onClick = { onLandmarkClick(landmark.id) }
                        )
                    }
                }
            }
        }
    }
}

