@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun DetailScreen(
    viewModel: DetailViewModel,
    landmarkId: String,
    onBack: () -> Unit,
    onAskTarek: (String) -> Unit,
    onOpenMap: (String) -> Unit
) {
    val landmark by viewModel.landmark.collectAsState()
    LaunchedEffect(landmarkId) { viewModel.loadLandmark(landmarkId) }

    val lm = landmark
    if (lm == null) {
        Scaffold(
            topBar = {
                CenterAlignedTopAppBar(
                    title = { Text("Landmark details") },
                    navigationIcon = {
                        FilledIconButton(onClick = onBack, modifier = Modifier.padding(start = 8.dp)) {
                            Icon(Icons.AutoMirrored.Rounded.ArrowBack, contentDescription = "Back")
                        }
                    }
                )
            }
        ) { padding ->
            Box(
                modifier = Modifier.fillMaxSize().padding(padding),
                contentAlignment = Alignment.Center
            ) {
                CircularProgressIndicator()
            }
        }
        return
    }

    DetailContent(
        landmark = lm,
        onBack = onBack,
        onAskTarek = onAskTarek,
        onOpenMap = onOpenMap
    )
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun DetailContent(
    landmark: Landmark,
    onBack: () -> Unit,
    onAskTarek: (String) -> Unit,
    onOpenMap: (String) -> Unit
) {
    Scaffold(
        containerColor = MaterialTheme.colorScheme.background,
        topBar = {
            CenterAlignedTopAppBar(
                title = { Text(landmark.name) },
                navigationIcon = {
                    FilledIconButton(onClick = onBack, modifier = Modifier.padding(start = 8.dp)) {
                        Icon(Icons.AutoMirrored.Rounded.ArrowBack, contentDescription = "Back")
                    }
                }
            )
        },
        bottomBar = {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(12.dp),
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                ElevatedButton(
                    onClick = { onAskTarek(landmark.id) },
                    modifier = Modifier.weight(1f)
                ) {
                    Icon(Icons.Rounded.ChatBubbleOutline, contentDescription = null)
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("Ask Tarek")
                }
                Button(
                    onClick = { onOpenMap(landmark.id) },
                    modifier = Modifier.weight(1f)
                ) {
                    Icon(Icons.Rounded.LocationOn, contentDescription = null)
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("View on Map")
                }
            }
        }
    ) { padding ->
        TunisianPatternBackground(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .verticalScroll(rememberScrollState())
                    .padding(horizontal = 16.dp, vertical = 10.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Text(text = landmark.city, style = MaterialTheme.typography.titleMedium)

                val gallery = landmark.images.filter { it.isNotBlank() }
                    .ifEmpty { listOf(landmark.imageUrl).filter { it.isNotBlank() } }

                LazyRow(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                    items(gallery) { image ->
                        Card(shape = RoundedCornerShape(16.dp)) {
                            AsyncImage(
                                model = image,
                                contentDescription = landmark.name,
                                modifier = Modifier.size(260.dp, 165.dp),
                                contentScale = ContentScale.Crop
                            )
                        }
                    }
                }

                HeritageChips()
                InfoCard("Cultural Story", landmark.description)
                InfoCard("Echoes of History", landmark.history)
                Spacer(modifier = Modifier.height(8.dp))
            }
        }
    }
}

@Composable
private fun HeritageChips() {
    val chips = listOf("UNESCO Spirit", "Roman Legacy", "Amazigh Roots", "Mediterranean Soul")
    LazyRow(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
        items(chips) { chip ->
            AssistChip(onClick = {}, label = { Text(chip) })
        }
    }
}

@Composable
private fun InfoCard(title: String, text: String) {
    Card(
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)
    ) {
        Column(
            modifier = Modifier.padding(14.dp),
            verticalArrangement = Arrangement.spacedBy(6.dp)
        ) {
            Text(text = title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold)
            Text(text = text, style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurfaceVariant)
        }
    }
}

